import{_ as i,a0 as l,w as o,s as r,ao as d,I as p,x as n,a1 as e,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"使用 Linux 終端查看你的電腦上有哪些文件 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Linux 終端查看你的電腦上有哪些文件 | LCTT (202108) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Linux 終端查看你的電腦上有哪些文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Linux 終端查看你的電腦上有哪些文件 | LCTT (202108) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202108/20210801 Use the Linux terminal to see what files are on your computer","title":"使用 Linux 終端查看你的電腦上有哪些文件","tag":"202108","desc":""},"relativePath":"202108/20210801 Use the Linux terminal to see what files are on your computer.md","filePath":"[post].md"}'),u={name:"202108/20210801 Use the Linux terminal to see what files are on your computer.md"};function c(h,s,m,x,f,g){const a=l("Link");return o(),r("div",null,[s[15]||(s[15]=d(`<h1 id="使用-linux-終端查看你的電腦上有哪些文件" tabindex="-1">使用 Linux 終端查看你的電腦上有哪些文件 <a class="header-anchor" href="#使用-linux-終端查看你的電腦上有哪些文件" aria-label="Permalink to “使用 Linux 終端查看你的電腦上有哪些文件”">​</a></h1><blockquote><p>通過這個 Linux 教程學習如何使用 ls 命令在終端中列出文件。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202108/11/142450etebpqtp7bl4kupt.jpg" alt=""></p><p>要在有圖形界面的計算機上列出文件，你通常可以打開一個文件管理器（Linux 上的 “文件”，MacOS 上的 “訪達”，Windows 上的 “文件資源管理器”）來查看文件。</p><p>要在終端中列出文件，你可以使用 <code>ls</code> 命令來列出當前目錄中的所有文件。而 <code>pwd</code> 命令可以告訴你當前所在的目錄：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>example.txt</span></span>
<span class="line"><span>Documents</span></span>
<span class="line"><span>Downloads</span></span>
<span class="line"><span>Music</span></span>
<span class="line"><span>Pictures</span></span>
<span class="line"><span>Templates</span></span>
<span class="line"><span>Videos</span></span></code></pre></div><p>你可以通過 <code>--all</code>（簡寫為 <code>-a</code>） 選項看到隱藏文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux</span></span>
<span class="line"><span>$ ls --all</span></span>
<span class="line"><span>.               Downloads</span></span>
<span class="line"><span>..              .local</span></span>
<span class="line"><span>.bashrc         Music</span></span>
<span class="line"><span>.config         Pictures</span></span>
<span class="line"><span>example.txt     Templates</span></span>
<span class="line"><span>Documents       Videos</span></span></code></pre></div><p>如你所見，列出的前兩項是點。單個點（<code>.</code>）實際上是一個元位置，代表 <em>你當前所在的文件夾</em> 。兩個點（<code>..</code>）表示你可以從當前位置返回的上級目錄。也就是説，當前目錄在另一個文件夾中。當你在計算機目錄間移動時，你就可以利用這些元位置為自己創建快捷方式，或者增加你的路徑的獨特性。</p><h3 id="文件和文件夾以及如何區分它們" tabindex="-1">文件和文件夾以及如何區分它們 <a class="header-anchor" href="#文件和文件夾以及如何區分它們" aria-label="Permalink to “文件和文件夾以及如何區分它們”">​</a></h3><p>你可能會注意到，文件和文件夾是很難區分的。一些 Linux 發行版有一些漂亮的顏色設置，比如所有的文件夾都是藍色的，文件是白色的，二進制文件是粉色或綠色的，等等。如果你沒有看到這些顏色，你可以試試 <code>ls --color</code>。如果你有色盲症或者使用的不是彩色顯示器，你可以使用 <code>--classify</code> 選項替代：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ pwd</span></span>
<span class="line"><span>/home/tux/Downloads</span></span>
<span class="line"><span>$ ls --classify</span></span>
<span class="line"><span>android-info.txt</span></span>
<span class="line"><span>cheat/</span></span>
<span class="line"><span>test-script.sh*</span></span></code></pre></div><p>你會發現，文件夾末尾加了一個斜槓（<code>/</code>），以表示它們是文件系統中的某一級目錄。而二進制文件，如壓縮文件和可執行程序，用星號（<code>*</code>）標記。</p><hr>`,14)),p("p",null,[s[1]||(s[1]=n("via: ",-1)),e(a,{href:"https://opensource.com/article/21/8/linux-list-files"},{default:t(()=>[...s[0]||(s[0]=[n("https://opensource.com/article/21/8/linux-list-files",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=n("作者：",-1)),e(a,{href:"https://opensource.com/users/seth"},{default:t(()=>[...s[2]||(s[2]=[n("Seth Kenlon",-1)])]),_:1}),s[7]||(s[7]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[3]||(s[3]=[n("lujun9972",-1)])]),_:1}),s[8]||(s[8]=n(" 譯者：",-1)),e(a,{href:"https://github.com/piaoshi"},{default:t(()=>[...s[4]||(s[4]=[n("piaoshi",-1)])]),_:1}),s[9]||(s[9]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:t(()=>[...s[5]||(s[5]=[n("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[10]||(s[10]=[n("LCTT",-1)])]),_:1}),s[13]||(s[13]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:t(()=>[...s[11]||(s[11]=[n("Linux中國",-1)])]),_:1}),s[14]||(s[14]=n(" 榮譽推出",-1))])])}const L=i(u,[["render",c]]);export{T as __pageData,L as default};
